// Internal mock user shape — includes a plaintext "password" since this
// only ever lives in memory in the browser for the offline fallback; the
// real backend (see database/init.sql + authService.ts) stores a proper
// bcrypt hash instead.
interface MockUser extends User {
  password: string;
}

function toPublicUser(u: MockUser): User {
  const { password: _drop, ...user } = u;
  return user;
}

