  "Preload vs prefetch": [{ text: "preload tells the browser to fetch a resource needed for the CURRENT page with high priority as soon as possible; prefetch fetches a resource likely needed for a FUTURE navigation, at low priority during idle time.", is_correct: true }, { text: "They are identical hints; the names are just aliases for the same behavior.", is_correct: false }, { text: "prefetch is for the current page and preload is for future navigations.", is_correct: false }],
  "Image formats": [{ text: "They typically achieve significantly smaller file sizes at comparable visual quality through more efficient compression, reducing page weight and load time.", is_correct: true }, { text: "WebP and AVIF always look worse than JPEG regardless of file size.", is_correct: false }, { text: "Modern image formats can only be used for icons, never photographs.", is_correct: false }],
  "Debouncing scroll/resize handlers": [{ text: "These events can fire dozens of times per second; running expensive work (like layout calculations) on every single event can jank the UI, so limiting how often the handler actually runs keeps things smooth.", is_correct: true }, { text: "Debouncing these handlers is purely a code-style preference with no performance effect.", is_correct: false }, { text: "Scroll and resize events only fire once per page, so throttling has no effect.", is_correct: false }],
  "List virtualization": [{ text: "Rendering thousands of DOM nodes for a huge list is slow and memory-intensive; virtualization renders only the rows currently visible in the viewport (plus a small buffer), dramatically improving render and scroll performance.", is_correct: true }, { text: "Virtualization pre-renders the entire list off-screen ahead of time.", is_correct: false }, { text: "It only applies to images, not text-based list rows.", is_correct: false }],
  "Minification and bundling": [{ text: "Minification strips whitespace/comments and shortens identifiers to reduce file size; bundling combines many modules into fewer files, reducing the number of separate network requests the browser must make.", is_correct: true }, { text: "Minification and bundling both work exclusively on image assets.", is_correct: false }, { text: "Bundling always increases the number of requests, which is the trade-off for minification.", is_correct: false }],
  "HTTP/2 multiplexing": [{ text: "It allows many requests and responses to be interleaved over a single TCP connection concurrently, avoiding the head-of-line blocking and per-domain connection limits that made HTTP/1.1 rely on techniques like domain sharding.", is_correct: true }, { text: "Multiplexing means every request opens its own dedicated TCP connection, like HTTP/1.1.", is_correct: false }, { text: "HTTP/2 multiplexing only applies to image requests, not scripts or stylesheets.", is_correct: false }],
  "Service workers and caching": [{ text: "It runs as a network proxy in the browser, letting you cache assets and API responses with custom strategies (cache-first, network-first, stale-while-revalidate), serving them instantly on repeat visits or even without a network connection.", is_correct: true }, { text: "Service workers replace the need for a backend server entirely.", is_correct: false }, { text: "Service workers can only cache HTML documents, not other asset types.", is_correct: false }],
  "Layout thrashing": [{ text: "Repeatedly interleaving DOM reads (like offsetHeight) and writes (like style changes) in a loop forces the browser to recalculate layout synchronously on every iteration; batching all reads first, then all writes, avoids the repeated forced reflows.", is_correct: true }, { text: "Layout thrashing is caused exclusively by using too many CSS classes.", is_correct: false }, { text: "It only happens when animations are implemented with JavaScript, never CSS.", is_correct: false }],
  "Font loading strategies": [{ text: "It controls how a web font is shown while it's still loading (e.g. swap shows fallback text immediately then swaps to the custom font), preventing invisible text (FOIT) from blocking content from being seen.", is_correct: true }, { text: "font-display controls the font's file size on disk.", is_correct: false }, { text: "It only affects which font weights are available, not loading behavior.", is_correct: false }],
  "Time to First Byte": [{ text: "The time between the client's request and the first byte of the server's response arriving, affected by network latency, server processing time (like slow database queries), and any redirects along the way.", is_correct: true }, { text: "TTFB measures how long it takes all images on the page to finish loading.", is_correct: false }, { text: "TTFB is entirely determined by the client's CPU speed, not the server.", is_correct: false }],
  "Resource hints": [{ text: "dns-prefetch resolves a domain's DNS ahead of time; preconnect goes further and also establishes the TCP/TLS connection early — both reduce the latency of a later request to that origin by doing setup work before it's actually needed.", is_correct: true }, { text: "They immediately download the full content of a linked page in the background.", is_correct: false }, { text: "These hints only work for same-origin requests, not third-party domains.", is_correct: false }],
  "Reducing JS execution time": [{ text: "Code-split and lazy-load non-critical JS, remove unused code (tree shaking), avoid large synchronous work on the main thread (offload to Web Workers when possible), and minimize expensive re-renders in UI frameworks.", is_correct: true }, { text: "Execution time can only be reduced by upgrading the user's hardware.", is_correct: false }, { text: "Minification alone eliminates all JavaScript execution time on the main thread.", is_correct: false }],
