// Mutable in-memory store for create/update/delete operations in mock mode.
// nextQuestionId starts after the last seeded id (mockQuestions now runs
// 1-260 across both seed batches — see mockQuestionsBatch2 above).
let nextQuestionId = mockQuestions.length + 1;
let nextInterviewId = 5;
let nextUserId = mockUsers.length + 1;

export const mockStore = {
  questions: [...mockQuestions],
  interviews: [...mockInterviews],
  categories: [...mockCategories],
  users: [...mockUsers],
  nextQuestionId: () => nextQuestionId++,
  nextInterviewId: () => nextInterviewId++,

  // --- Mock auth ---------------------------------------------------
  // Mirrors the real backend's /api/auth endpoints closely enough for the
  // UI to behave the same offline: register/login return {user, token},
  // and interview endpoints scope by the "logged in" user. Tokens here are
  // just "mock:<userId>" — there's nothing to verify, this only runs
  // locally when the real backend is unreachable.
  registerUser(data: { name: string; email: string; password: string }): { user: User; token: string } {
    const name = data.name?.trim();
    const email = data.email?.trim().toLowerCase();
    if (!name) throw new Error("Name is required");
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error("A valid email is required");
    if (!data.password || data.password.length < 8) throw new Error("Password must be at least 8 characters");
    if (this.users.some((u) => u.email === email)) throw new Error("Email already registered");

    const user: MockUser = { id: nextUserId++, name, email, password: data.password, created_at: new Date().toISOString() };
    this.users.push(user);
    setToken(`mock:${user.id}`);
    return { user: toPublicUser(user), token: `mock:${user.id}` };
  },

  loginUser(data: { email: string; password: string }): { user: User; token: string } {
    const email = data.email?.trim().toLowerCase();
    const found = this.users.find((u) => u.email === email);
    if (!found || found.password !== data.password) {
      throw new Error("Invalid email or password");
    }
    setToken(`mock:${found.id}`);
    return { user: toPublicUser(found), token: `mock:${found.id}` };
  },

  // Returns the user for the current mock token, or null if logged out.
  currentMockUser(): User | null {
    const token = getToken();
    const id = token?.startsWith("mock:") ? Number(token.slice(5)) : null;
    const found = id ? this.users.find((u) => u.id === id) : undefined;
    return found ? toPublicUser(found) : null;
  },

  // Same as currentMockUser but throws when logged out, matching the real
  // backend's 401 for every interview endpoint.
  requireMockUser(): User {
    const user = this.currentMockUser();
    if (!user) throw new Error("Authentication required");
    return user;
  },
};
